impl RequirementStatus {
    /// Whether the requirement is satisfied (tool available and ready).
    pub fn is_satisfied(&self) -> bool {
        matches!(self, RequirementStatus::Satisfied)
    }

    /// Whether the step can proceed (possibly with warnings).
    pub fn can_proceed(&self) -> bool {
        matches!(
            self,
            RequirementStatus::Satisfied | RequirementStatus::SystemOnly { .. }
        )
    }

    /// Human-readable summary of this status for dry-run output.
    pub fn dry_run_summary(&self) -> String {
        match self {
            RequirementStatus::Satisfied => "satisfied".to_string(),
            RequirementStatus::SystemOnly { path, .. } => {
                format!("system-only ({})", path.display())
            }
            RequirementStatus::Inactive { manager, .. } => {
                format!("inactive (managed by {})", manager)
            }
            RequirementStatus::ServiceDown {
                start_command,
                start_hint,
                ..
            } => {
                if let Some(cmd) = start_command {
                    format!("service down, would start: {}", cmd)
                } else {
                    format!("service down ({})", start_hint)
                }
            }
            RequirementStatus::Missing { install_hint, .. } => {
                if let Some(hint) = install_hint {
                    format!("missing, would install: {}", hint)
                } else {
                    "missing (no install method)".to_string()
                }
            }
            RequirementStatus::Unknown => "unknown requirement".to_string(),
        }
    }
}

