        let result = runner
            .run(&options, &ctx, &HashMap::new(), temp.path())
            .unwrap();

        assert!(!result.success);
        // Only a ran; b and c were blocked
        assert_eq!(result.steps.len(), 1);
        assert_eq!(result.steps[0].name, "a");
        assert!(!marker_b.exists());
        assert!(!marker_c.exists());
    }

